import os
import re

# Fix all breadcrumb URLs that are missing the leading slash
def fix_breadcrumb_urls\(\):
    for root, dirs, files in os.walk\('src/pages'\):
        for file in files:
            if file == 'index.astro':
                filepath = os.path.join\(root, file\)

                with open\(filepath, 'r', encoding='utf-8'\) as f:
                    content = f.read\(\)

                # Fix missing leading slashes in Home URLs
                if "url: 'en-us/'" in content:
                    content = content.replace\("url: 'en-us/'", "url: '/en-us/'"\)
                if "url: 'it-it/'" in content:
                    content = content.replace\("url: 'it-it/'", "url: '/it-it/'"\)
                if "url: 'de-de/'" in content:
                    content = content.replace\("url: 'de-de/'", "url: '/de-de/'"\)
                if "url: 'fr-fr/'" in content:
                    content = content.replace\("url: 'fr-fr/'", "url: '/fr-fr/'"\)
                if "url: 'es-es/'" in content:
                    content = content.replace\("url: 'es-es/'", "url: '/es-es/'"\)

                # Check if we made changes
                with open\(filepath, 'r', encoding='utf-8'\) as f:
                    original = f.read\(\)

                if content != original:
                    with open\(filepath, 'w', encoding='utf-8'\) as f:
                        f.write\(content\)

fix_breadcrumb_urls\(\)
print\("Fixed breadcrumb URL leading slashes"\)
EOF)
